// tokenbucket.go
package ratelimit

import (
	"errors"
	"fmt"
	"math"
	"sync"
	"time"
)

type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

type TokenBucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

func NewTokenBucket(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, fmt.Errorf("ratelimit: capacity must be > 0, got %d", capacity)
	}
	if math.IsNaN(ratePerSecond) || math.IsInf(ratePerSecond, 0) || ratePerSecond <= 0 {
		return nil, fmt.Errorf("ratelimit: rate must be finite and > 0, got %v", ratePerSecond)
	}
	return &TokenBucket{
		clock:    clock,
		capacity: float64(capacity),
		rate:     ratePerSecond,
		tokens:   float64(capacity),
		last:     clock.Now(),
	}, nil
}

func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	if elapsed := now.Sub(b.last); elapsed > 0 {
		b.tokens = min(b.capacity, b.tokens+elapsed.Seconds()*b.rate)
		b.last = now
	}
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

func (b *TokenBucket) Allow() bool {
	return b.AllowN(1)
}

func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	now := b.clock.Now()
	if elapsed := now.Sub(b.last); elapsed > 0 {
		b.tokens = min(b.capacity, b.tokens+elapsed.Seconds()*b.rate)
		b.last = now
	}
	return b.tokens
}
